package com.example.domain

data class StarterCheck(val prompt: String, val options: List<String>, val answer: Int, val explanation: String)
data class StarterLesson(val title: String, val firstStep: String, val explanation: String, val worked: String,
    val recall: String, val practice: String, val reference: String, val checks: List<StarterCheck>) {
    fun score(choices: List<Int>): Int {
        require(choices.size == checks.size && choices.indices.all { choices[it] in checks[it].options.indices })
        return choices.indices.count { choices[it] == checks[it].answer }
    }
}

